export const calculateCarbonMetrics = (userData, previousCredits = 0) => {
  console.log("🔄 Received userData:", userData);

  // Emission factors (adjust as needed)
  const emissionFactors = {
    electricity: 0.5, // kg CO₂ per kWh
    transportation: 0.2, // kg CO₂ per km
    waste: 0.1 // kg CO₂ per kg
  };

  // Calculate carbon footprint
  const footprint =
    (userData.electricity || 0) * emissionFactors.electricity +
    (userData.vehicleMiles || 0) * emissionFactors.transportation +
    (userData.airTravel || 0) * emissionFactors.transportation +
    (userData.wasteProduced || 0) * emissionFactors.waste;

  console.log("🌍 Calculated footprint:", footprint, "kg CO₂");

  // Award credits based on footprint
  const CREDITS_PER_KG = 0.5; // Earn 0.5 credits per kg CO₂
  const dailyCredits = footprint * CREDITS_PER_KG;

  console.log("💰 Credits earned today:", dailyCredits);

  // Accumulate credits from previous days
  const totalCredits = previousCredits + dailyCredits;
  console.log("📊 Updated total credits:", totalCredits);

  // Calculate progress percentage based on a daily goal
  const TARGET_FOOTPRINT = 20; // Example: Encourage users to stay under 20kg CO₂/day
  const progress = (footprint / TARGET_FOOTPRINT) * 100;
  console.log("📈 Progress towards target:", progress, "%");

  // Convert to numbers to avoid Firestore storing as string
  const result = {
    totalCarbon: parseFloat(footprint.toFixed(1)),
    dailyCredits: parseFloat(dailyCredits.toFixed(1)),
    totalCredits: parseFloat(totalCredits.toFixed(1)), // Updated total
    progress: parseFloat(progress.toFixed(1)),
  };

  console.log("✅ Final calculated metrics:", result);

  return result;
};
